import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

def solve_problem():
    count = 0
    upper_bound = 200

    for n in range(2, upper_bound):
        if gcd(n, 6) != 1:
