        a_max = math.floor(n / 2)

        for a in range(a_min, a_max + 1):
            D = n - 2 * a

            # The condition is D | C(a-1, D-1)
            N = a - 1
            K = D - 1

            # Check if the condition is trivially satisfied (C=0)
            if K < 0 or K > N:
                # This should ideally not happen given the bounds derivation, 
                # but if it results in 0, the condition D | 0 holds for D >= 1.
                if combinations(N, K) == 0:
